    hS+=Math.sin(d*f*0.5-t*sp*0.3+3.0)*0.6;
  }
  const act=aS/10,inh=iS/10,harm=hS/10;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.08+t*0.5)*Math.cos(sy*0.06-t*0.7)*0.15;
  const bg=bg1+bg2+bg3;
  const dist1=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang1=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist1*0.05-ang1*3-t*1.5)+Math.sin(dist1*0.04+ang1*4-t*1.2))*0.35;
