  const sp3=Math.sin(dist3*0.07-ang3*4-t*1.3)*0.2;
  const spiral=sp1+sp2+sp3;
  const rd=Math.tanh((act-inh*0.65+harm*0.35+bg*0.25+spiral)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+sy*0.2+t*3)*Math.cos(sx*0.2-sy*0.3-t*2.5)*0.08;
  const edge=Math.abs(rd)>0.65?1.12:(Math.abs(rd)>0.5?1.04:1.0);
  const blend=rd*0.65+cell*0.2+micro+spiral*0.15,v=blend*0.5+0.5;
  const pal=[[5,12,45],[10,35,80],[15,70,120],[20,120,140],[40,170,150],[120,210,160],[200,220,140],[240,200,90],[230,150,70],[200,90,60],[160,50,70],[100,30,65],[50,20,55],[20,15,50],[5,12,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
